/* An absolute address in the prologue moves with ASLR: add the relocation delta. */
static void relocate(uint8_t *expect, int off)
{
    uint32_t v;
    memcpy(&v, expect + off, 4);
    v += (uint32_t)(sr_base - 0x400000u);
    memcpy(expect + off, &v, 4);
}

